// ============================================================
// VERIFICAR COOLDOWN — WF5
// Última actualización: 16/10/2026 (sesión 16) — 13.7.2
// ------------------------------------------------------------
// El tiempo de absorción ya NO se define acá. Lo define `vista_ultimo_riego`
// (columna `absorcion_completa`, 15 min), que es la misma columna que usa el
// recheck del Motor de WF1. Una sola definición: si mañana el piloto dice que
// son 25 minutos, se cambia en un lugar y los dos consumidores quedan de acuerdo.
// ============================================================
const ultimoRiego = $input.first().json;

// `{}` de alwaysOutputData = este cultivo nunca regó.
const hayRiego = !!(ultimoRiego && ultimoRiego.fecha_inicio);

// Validación positiva: si hay un riego, la vista tiene que decir si se absorbió.
// Sin ese dato no se riega: regar de más no se corrige, regar de menos sí.
if (hayRiego && typeof ultimoRiego.absorcion_completa !== 'boolean') {
  throw new Error('vista_ultimo_riego no trae absorcion_completa: falta aplicar SQL/sesion16_lazo_riego.sql. No se riega sin saber si el riego anterior se absorbió.');
}

return [{ json: { cooldown_activo: hayRiego && ultimoRiego.absorcion_completa === false } }];

// ============================================================
// CALCULAR DOSIS — WF5
// Última actualización: 27/10/2026 (sesión 20) — 16.51 y la dosis entregada
// ------------------------------------------------------------
// 16.51: antes, si faltaba el volumen o el caudal, se inventaban (`|| 10`, `|| 50`)
// y se regaba igual. Con el caudal en null, el 26/10 se registró un pulso de 13 s
// donde con el caudal real (40 ml/s) correspondían 16 s. Ahora, sin esos datos, no
// se riega: el mismo criterio que ya se aplicaba a los umbrales.
// Desde el 27/10, WF1 no llama a WF5 si falta alguno (`riego_automatico_disponible`,
// en la vista). Esta es la segunda defensa, por si algo llama a WF5 de otra forma.
//
// Dosis entregada: `dosis_ml` es el agua que sale de verdad (pulso x caudal), no la
// calculada. El tope de 30 s recorta: se calculaban 1.375 ml y salían 1.200, y el
// registro y el Telegram decían 1.375.
// ============================================================
const FACTOR_RETENCION_HIDRICA = 0.25; // fracción del volumen de maceta que retiene agua disponible
const MAX_DURACION_RIEGO_SEG = 30;     // tope de seguridad — nunca más de 30s por pulso
const MIN_DURACION_RIEGO_SEG = 3;      // pulso mínimo con sentido físico

const w = $('Webhook').first().json;
const cultivo = w.body || w;

// Fail-safe: sin umbrales no hay dosis segura posible. Preferimos no regar a regar a ciegas.
const rangoHumedad = (cultivo.umbrales || {}).humedad || {};
if (rangoHumedad.min == null || rangoHumedad.max == null) {
  throw new Error('No llegaron los umbrales de humedad — se aborta el riego en vez de usar un default.');
}

// La ausencia se decide ANTES de convertir: Number(null) === 0 y Number('') === 0.
const numOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// 16.51 — sin volumen o sin caudal no hay dosis posible. Un 0 tampoco sirve.
const volumenLitros = numOrNull(cultivo.volumen_maceta_litros);
const caudal        = numOrNull(cultivo.caudal_bomba_ml_s);
if (!(volumenLitros > 0) || !(caudal > 0)) {
  throw new Error(
    `Falta el volumen de la maceta (${cultivo.volumen_maceta_litros ?? 'vacío'}) o el caudal de la bomba ` +
    `(${cultivo.caudal_bomba_ml_s ?? 'vacío'}) — no se riega con un dato inventado (16.51). ` +
    `WF1 no debería haber llamado: revisar riego_automatico_disponible.`
  );
}

// Mismo criterio para la humedad: un null convertido a 0 sería el déficit máximo.
const humedadActual = numOrNull(cultivo.humedad);
if (humedadActual === null) {
  throw new Error('Llegó a WF5 sin humedad — no se riega sin saber cuánto falta.');
}
const humedadObjetivo = (rangoHumedad.min + rangoHumedad.max) / 2; // centro del rango ideal

const deficitPct = humedadObjetivo - humedadActual;
if (deficitPct <= 0) {
  throw new Error(`Llegó a WF5 sin déficit real (humedad ${humedadActual}% vs objetivo ${humedadObjetivo}%). Revisar el ruteo de WF1.`);
}

const dosisCalculadaMl = volumenLitros * 1000 * FACTOR_RETENCION_HIDRICA * (deficitPct / 100);

let duracionSeg = Math.round(dosisCalculadaMl / caudal);
duracionSeg = Math.min(Math.max(duracionSeg, MIN_DURACION_RIEGO_SEG), MAX_DURACION_RIEGO_SEG);

// Lo que sale de verdad por la manguera, después del tope.
const dosisEntregadaMl = duracionSeg * caudal;

return [{
  json: {
    cultivo_id:         cultivo.cultivo_id,
    dispositivo_id:     cultivo.dispositivo_id,
    planta:             cultivo.planta,
    humedad:            humedadActual,
    humedad_objetivo:   humedadObjetivo,
    dosis_ml:           Math.round(dosisEntregadaMl),  // la entregada: es la que se guarda y se informa
    dosis_calculada_ml: Math.round(dosisCalculadaMl),  // la que pedía el cálculo, antes del tope
    duracion_segundos:  duracionSeg,
    dosis_recortada:    (dosisCalculadaMl / caudal) > MAX_DURACION_RIEGO_SEG
  }
}];
